      type: "MCQ",
      text: `<p> Consider the following statements:<br/> 1. Slip occurs more readily when the atoms are far away from each other.<br/> 2. The direction in which the dislocation moves is called the slip direction, and the planes impacted by the slip are called the slip planes.<br/> 3. The stress required to induce slip increases exponentially with increasing interplanar spacing.<br/>Which of the above statements is/are correct? </p>`,
