      answer: "B",
      solution: `<p> (b)<br/> The contour interval (the vertical distance between adjacent contour lines) is kept constant for a<br/> single map to ensure a consistent representation of the terrain. For steep terrain, a larger standard<br/> contour interval might be chosen for the entire map to prevent the lines from being too close<br/> together and unreadable; in flat terrain, a smaller contour interval is used. However, the interval<br/>remains uniform across the map. </p>`,
