      solution: `<p> (c)<br/> •Profile levelling provides the vertical data (elevations) along the center line, which determines the depth of cut or the height of fill needed at different points.<br/> •Cross-sectioning provides the necessary data to determine the area of the earthwork section of vanous intervals along the route<br/> By combining the areas from the cross-sections with the distances between them (derived from<br/> the profile and plan view), engineers can calculate the precise volumes of material that must be<br/> excavated (cut) or added (fill) to achieve the final desired ground level or formation level. This<br/>process is fundamental for efficient and cost-effective earthwork construction </p>`,
